# area: inheritance_mro
# hypothesis: Cooperative super() calls in a diamond follow the C3 MRO at runtime, and an override that narrows a parameter type is an LSP error that mypy and ty report but CPython accepts.
from typing import reveal_type


class Base:
    def greet(self) -> list[str]:
        return ['base']


class Left(Base):
    def greet(self) -> list[str]:
        return ['left'] + super().greet()


class Right(Base):
    def greet(self) -> list[str]:
        return ['right'] + super().greet()


class Diamond(Left, Right):
    def greet(self) -> list[str]:
        return ['diamond'] + super().greet()


d = Diamond()
print(d.greet())
print([c.__name__ for c in Diamond.__mro__])
reveal_type(d.greet())


class Animal:
    def feed(self, food: str) -> None:
        print('feed', food)


class Cat(Animal):
    def feed(self, food: int) -> None:  # expect-error
        print('cat', food)


Animal().feed('kibble')
Cat().feed(3)
